#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    size_t n = 4;
    int *a = malloc(n * sizeof(int));
    if (!a) return 1;
    for (size_t i = 0; i < n; i++) a[i] = (int)i;

    size_t new_n = 8;
    int *tmp = realloc(a, new_n * sizeof(int));   /* 用临时变量接 */
    if (!tmp) { free(a); return 1; }
    a = tmp;

    for (size_t i = n; i < new_n; i++) a[i] = (int)(i * 100);

    for (size_t i = 0; i < new_n; i++) printf("%d%c", a[i], i + 1 == new_n ? '\n' : ' ');
    printf("原有 %zu 个元素已保留\n", n);
    free(a); a = NULL;
    return 0;
}
